import { Component, inject, computed, effect, ViewChild, ElementRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FinancialService } from '../../core/services/financial.service';
import { FinancialTableComponent } from '../../shared/components/financial-table/financial-table.component';
import { KpiCardComponent } from '../../shared/components/kpi-card/kpi-card.component';
import { Chart, registerables } from 'chart.js';

Chart.register(...registerables);

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, FinancialTableComponent, KpiCardComponent],
  templateUrl: './dashboard.component.html'
})
export class DashboardComponent {
  financialService = inject(FinancialService);
  Object = Object;

  // Referências para os Canvas dos Gráficos solicitados
  @ViewChild('chartAtivo') chartAtivo!: ElementRef;
  @ViewChild('chartPassivo') chartPassivo!: ElementRef;
  @ViewChild('chartEvolucao') chartEvolucao!: ElementRef;
  @ViewChild('chartDre') chartDre!: ElementRef;

  private charts: Chart[] = [];

  constructor() {
    // Redesenha os gráficos sempre que os dados do sinal mudarem
    effect(() => {
      const data = this.financialService.dashboardData();
      if (data && data.graficos) {
        setTimeout(() => this.initCharts(data), 100);
      }
    });
  }

  private initCharts(data: any) {
    this.charts.forEach(c => c.destroy());
    this.charts = [];

    const commonOptions = { 
      responsive: true, 
      maintainAspectRatio: false 
    };

    // 1. Gráfico de Rosca: Composição do Ativo
    this.charts.push(new Chart(this.chartAtivo.nativeElement, {
      type: 'doughnut',
      data: {
        labels: data.graficos.composicao_ativo.map((i: any) => i.name),
        datasets: [{
          data: data.graficos.composicao_ativo.map((i: any) => i.value),
          backgroundColor: ['#10b981', '#e2e8f0'],
          hoverOffset: 4
        }]
      },
      options: { 
        ...commonOptions, 
        cutout: '60%', // CORREÇÃO: Fora de plugins
        plugins: { 
          legend: { position: 'bottom' } 
        } 
      }
    }));

    // 2. Gráfico de Rosca: Composição do Passivo
    this.charts.push(new Chart(this.chartPassivo.nativeElement, {
      type: 'doughnut',
      data: {
        labels: data.graficos.composicao_passivo.map((i: any) => i.name),
        datasets: [{
          data: data.graficos.composicao_passivo.map((i: any) => i.value),
          backgroundColor: ['#f43f5e', '#94a3b8', '#10b981'],
          hoverOffset: 4
        }]
      },
      options: { 
        ...commonOptions, 
        cutout: '60%', // CORREÇÃO: Fora de plugins
        plugins: { 
          legend: { position: 'bottom' } 
        } 
      }
    }));

    // 3. Gráfico de Linha: Evolução Patrimonial
    this.charts.push(new Chart(this.chartEvolucao.nativeElement, {
      type: 'line',
      data: {
        labels: data.graficos.evolucao_patrimonial.categorias,
        datasets: [
          {
            label: 'Ano Anterior',
            data: data.graficos.evolucao_patrimonial.anterior,
            borderColor: '#94a3b8',
            backgroundColor: 'rgba(148, 163, 184, 0.1)',
            fill: true,
            tension: 0.4
          },
          {
            label: 'Ano Atual',
            data: data.graficos.evolucao_patrimonial.atual,
            borderColor: '#10b981',
            backgroundColor: 'rgba(16, 185, 129, 0.1)',
            fill: true,
            tension: 0.4
          }
        ]
      },
      options: commonOptions
    }));

    // 4. Gráfico de Coluna: DRE Performance
    this.charts.push(new Chart(this.chartDre.nativeElement, {
      type: 'bar',
      data: {
        labels: data.graficos.dre.map((i: any) => i.name),
        datasets: [{
          label: 'Valor Nominal',
          data: data.graficos.dre.map((i: any) => i.valor),
          backgroundColor: '#10b981',
          borderRadius: 10
        }]
      },
      options: { 
        ...commonOptions, 
        plugins: { 
          legend: { display: false } 
        } 
      }
    }));
  }

  // ETAPA 6: Insights Dinâmicos atualizados
  pontosPositivos = computed(() => {
    const data = this.financialService.dashboardData();
    if (!data) return [];
    const items: string[] = [];
    const ind = data.indices;

    if (ind['roa'] > 15) items.push('✅ Excelente retorno sobre ativos (ROA), demonstrando uso eficiente da estrutura.'); 
    const lucroLiq = data.tabela_dre?.find(r => r.conta.toLowerCase().includes('lucro liq'));
    if (lucroLiq && lucroLiq.perc > 0) {
      items.push(`✅ Crescimento expressivo de ${lucroLiq.perc}% no Lucro Líquido.`);
    }
    return items;
  });

  pontosAtencao = computed(() => {
    const data = this.financialService.dashboardData();
    if (!data) return [];
    const items: string[] = [];
    const ind = data.indices;

    if (ind['liq_corrente'] < 1.0) items.push('⚠️ Liquidez corrente abaixo de 1.0 indica risco imediato de insolvência.'); 
    if (ind['endiv_geral'] > 70) items.push('⚠️ Endividamento Geral crítico acima de 70%, comprometendo a autonomia financeira.'); 
    return items;
  });

  getIndicatorClass(key: string, value: number): string {
    const k = key.toLowerCase();
    if (k.includes('liq_')) {
      if (value < 1.0) return 'text-rose-600 bg-rose-50 border-rose-100';
      return value <= 1.5 ? 'text-amber-600 bg-amber-50 border-amber-100' : 'text-emerald-600 bg-emerald-50 border-emerald-100';
    }
    if (k.includes('endiv_geral')) {
      return value > 70 ? 'text-rose-600 bg-rose-50 border-rose-100' : value > 50 ? 'text-amber-600 bg-amber-50 border-amber-100' : 'text-emerald-600 bg-emerald-50 border-emerald-100';
    }
    return (value < 10) ? 'text-amber-600 bg-amber-50 border-amber-100' : 'text-emerald-600 bg-emerald-50 border-emerald-100';
  }

  getIndicatorNote(key: string, value: number): string {
    const k = key.toLowerCase();
    if (k.includes('liq_corrente')) return value < 1.0 ? '🚨 CRÍTICO: Insolvência a curto prazo' : '✅ ADEQUADO';
    if (k.includes('endiv_geral')) return value > 70 ? '🚨 CRÍTICO: Alavancagem perigosa' : '✅ SAUDÁVEL';
    if (k.includes('roe')) return value > 15 ? '✅ EXCELENTE: Retorno alto ao sócio' : '⚠️ BAIXO';
    return 'Análise Emerald Intelligence';
  }

  getAnosProcessados(anosObj: any): string {
    return anosObj ? Object.keys(anosObj).sort().join(' VS ') : '...';
  }

  onFileSelected(event: any) {
    const files = event.target.files;
    if (files.length) this.financialService.uploadFiles(Array.from(files)).subscribe();
  }

  print() { window.print(); } 
}
